const char *get_self();

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *python_printer(const char *s) {
    if (s == nullptr) return nullptr;

    static const char prefix[] = "import sys\nsys.stdout.write(\"";
    static const char suffix[] = "\")\n";

    size_t len = strlen(s);
    size_t cap = strlen(prefix) + (len * 4) + strlen(suffix) + 1;

    char *out = malloc(cap);
    if (out == nullptr) return nullptr;

    char *p = out;
    p += sprintf(p, "%s", prefix);

    for (const unsigned char *c = (const unsigned char *)s; *c; c++) {
      switch (*c) {
      case '\\':
      case '"':
      case '\n':
      case '\r': 
      case '\t':
        *p++ = '\\';
        *p++ = *c;
        break;
      default:
        if (*c >= 0x20 && *c < 0x7f)
          *p++ = (char)*c;
        else
          p += sprintf(p, "\\x%02x", *c);
        break;
      }
    }

    p += sprintf(p, "%s", suffix);
    return out;
}

int main(int argc, char **argv) {
  const char *self = get_self();
  char *python_version = python_printer(self);
  printf("%s", python_version);
  free(python_version);
  return 0;
}

const char*prologue="";
const char*selfref="";

size_t hex2bin(const char*hex,char**bin) {
  char*dst=*bin=malloc(strlen(hex)/2+1);
  while(*hex){sscanf(hex,"%2hhx",dst++),hex+=2;}
  return *dst=0,(dst-*bin);
}

const char*get_self() {
  static char*self;
  if (!self) {
    char*decP,*decSR;
    size_t cP=hex2bin(prologue,&decP),cSR=hex2bin(selfref,&decSR);
    self=malloc(cP+cSR+strlen(prologue)+strlen(selfref)+1000);
    sprintf(self,"%sconst char*prologue=%c%s%c;\nconst char*selfref=%c%s%c;\n\n%s",decP,34,prologue,34,34,selfref,34,decSR);
    free(decP),free(decSR);
  }
  return self;
}
